1	"use client";
2	
3	import { useRouter } from "next/navigation";
4	import { useEffect, useRef, useState } from "react";
5	import { ArrowUp, Paperclip, Mic, X, Gift, Sparkles } from "lucide-react";
6	import { motion } from "framer-motion";
7	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
8	import { SIGNUP_GRANT } from "@/lib/credits";
9	
10	// The rotating gradient inside each glow clip MUST be a square that is
11	// larger than the clip's diagonal, or it stops covering the clip partway
12	// through its own rotation and the ring visibly vanishes and returns on a
13	// loop. (The previous `inset-[-50%]` made it 2x the clip in BOTH axes —
14	// e.g. 1372x296 for this wide composer. Rotated 90deg that occupies
15	// 296x1372: only 296px wide, far short of the ~686px the clip needs
16	// covered. Hence "the glow keeps disappearing.")
17	//
18	// 200% width + aspectRatio 1 gives a square of side 2*clipWidth, which
19	// always exceeds the diagonal. Centering uses margins rather than a
20	// translate because `transform` is owned by the rotation keyframes and a
21	// transform in the animation would override any translate set here —
22	// percentage margins (all sides, per spec) resolve against the containing
23	// block's WIDTH, so -100% on both axes lands the square's center exactly
24	// on the clip's center.
25	const SPIN_SQUARE: React.CSSProperties = {
26	  position: "absolute",
27	  left: "50%",
28	  top: "50%",
29	  width: "200%",
30	  aspectRatio: "1",
31	  marginLeft: "-100%",
32	  marginTop: "-100%",
33	};
34	
35	const SUGGESTIONS = [
36	  "A portfolio site for a freelance photographer",
37	  "A landing page for my SaaS product",
38	  "A website for a neighborhood coffee shop",
39	  "A booking page for my consulting practice",
40	];
41	
42	// Downscale + re-encode client-side so a phone photo doesn't blow past
43	// sessionStorage's per-origin quota (or the tokens it costs Claude to look
44	// at it) — a reference image only needs to be legible, not full-resolution.
45	async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
46	  const bitmap = await createImageBitmap(file);
47	  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
48	  const w = Math.round(bitmap.width * scale);
49	  const h = Math.round(bitmap.height * scale);
50	  const canvas = document.createElement("canvas");
51	  canvas.width = w;
52	  canvas.height = h;
53	  const ctx = canvas.getContext("2d");
54	  if (!ctx) throw new Error("canvas unsupported");
55	  ctx.drawImage(bitmap, 0, 0, w, h);
56	  return canvas.toDataURL("image/jpeg", quality);
57	}
58	
59	type SpeechRecognitionLike = {
60	  continuous: boolean;
61	  interimResults: boolean;
62	  lang: string;
63	  start: () => void;
64	  stop: () => void;
65	  onresult: ((e: any) => void) | null;
66	  onend: (() => void) | null;
67	  onerror: (() => void) | null;
68	};
69	
70	function getSpeechRecognition(): (new () => SpeechRecognitionLike) | null {
71	  if (typeof window === "undefined") return null;
72	  return (window as any).SpeechRecognition ?? (window as any).webkitSpeechRecognition ?? null;
73	}
74	
75	export function PromptHero() {
76	  const router = useRouter();
77	  const [value, setValue] = useState("");
78	  const [focused, setFocused] = useState(false);
79	  const [image, setImage] = useState<string | null>(null);
80	  const [listening, setListening] = useState(false);
81	  const [speechSupported, setSpeechSupported] = useState(false);
82	  const [enhanceSupported, setEnhanceSupported] = useState(false);
83	  const [enhancing, setEnhancing] = useState(false);
84	  // The prompt as typed, kept only while an enhanced spec is on screen — this
85	  // is what "Revert" restores, and its presence is what tells the composer it
86	  // is currently showing a spec rather than a one-liner.
87	  const [enhancedFrom, setEnhancedFrom] = useState<string | null>(null);
88	  const [enhanceError, setEnhanceError] = useState<string | null>(null);
89	  const fileInputRef = useRef<HTMLInputElement>(null);
90	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
91	  const baseValueRef = useRef("");
92	
93	  useEffect(() => {
94	    setSpeechSupported(getSpeechRecognition() !== null);
95	  }, []);
96	
97	  // /api/enhance is auth-gated, and most people meeting this hero are signed
98	  // out — so the button appears only once we know it would work, the same way
99	  // the mic waits on feature detection above. Failing closed is the point:
100	  // an affordance that 401s on click is worse than no affordance.
101	  useEffect(() => {
102	    let alive = true;
103	    fetch("/api/auth/me")
104	      .then((res) => res.json())
105	      .then((body) => {
106	        if (alive && body?.user) setEnhanceSupported(true);
107	      })
108	      .catch(() => {});
109	    return () => {
110	      alive = false;
111	    };
112	  }, []);
113	
114	  async function enhance() {
115	    const text = value.trim();
116	    if (!text || enhancing) return;
117	
118	    setEnhancing(true);
119	    setEnhanceError(null);
120	    try {
121	      const res = await fetch("/api/enhance", {
122	        method: "POST",
123	        headers: { "Content-Type": "application/json" },
124	        // Always the ORIGINAL one-liner, never a spec we already produced —
125	        // enhancing an enhancement compounds invention instead of adding
126	        // detail, and the round trip would drift further from what was asked.
127	        body: JSON.stringify({ prompt: enhancedFrom ?? text }),
128	      });
129	      const body = await res.json().catch(() => ({}));
130	      if (!res.ok || !body?.spec) throw new Error(body?.error ?? "Couldn't expand that.");
131	      setEnhancedFrom(enhancedFrom ?? text);
132	      setValue(body.spec);
133	    } catch (err) {
134	      // Nothing is destroyed on failure: `value` still holds what they typed,
135	      // and the build button beside this was never disabled.
136	      setEnhanceError(err instanceof Error ? err.message : "Couldn't expand that.");
137	    } finally {
138	      setEnhancing(false);
139	    }
140	  }
141	
142	  function revert() {
143	    if (enhancedFrom === null) return;
144	    setValue(enhancedFrom);
145	    setEnhancedFrom(null);
146	    setEnhanceError(null);
147	  }
148	
149	  function submit() {
150	    const text = value.trim();
151	    if (!text) return;
152	    try {
153	      sessionStorage.setItem(PENDING_PROMPT_KEY, text);
154	      if (image) sessionStorage.setItem(PENDING_PROMPT_IMAGE_KEY, image);
155	      else sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
156	    } catch {}
157	    router.push("/signup");
158	  }
159	
160	  async function onPickImage(e: React.ChangeEvent<HTMLInputElement>) {
161	    const file = e.target.files?.[0];
162	    e.target.value = "";
163	    if (!file || !file.type.startsWith("image/")) return;
164	    try {
165	      setImage(await downscaleImage(file));
166	    } catch {}
167	  }
168	
169	  function toggleListening() {
170	    const Ctor = getSpeechRecognition();
171	    if (!Ctor) return;
172	
173	    if (listening) {
174	      recognitionRef.current?.stop();
175	      return;
176	    }
177	
178	    const rec = new Ctor();
179	    rec.continuous = true;
180	    rec.interimResults = true;
181	    rec.lang = "en-US";
182	    baseValueRef.current = value ? value.trim() + " " : "";
183	
184	    rec.onresult = (e: any) => {
185	      let transcript = "";
186	      for (let i = 0; i < e.results.length; i++) transcript += e.results[i][0].transcript;
187	      setValue((baseValueRef.current + transcript).trimStart());
188	    };
189	    rec.onend = () => setListening(false);
190	    rec.onerror = () => setListening(false);
191	
192	    recognitionRef.current = rec;
193	    rec.start();
194	    setListening(true);
195	  }
196	
197	  useEffect(() => () => recognitionRef.current?.stop(), []);
198	
199	  return (
200	    <div className="relative mx-auto w-full max-w-2xl">
201	      {/* Free-credits badge — the first thing a visitor should register
202	          about pricing, before they've even typed anything. Sits above the
203	          glow/composer group entirely (not inside its relative wrapper) so
204	          the glow below hugs just the box, not the badge too. */}
205	      <div className="mb-4 flex justify-center">
206	        <span className="inline-flex items-center gap-1.5 rounded-full border border-neutral-200/70 bg-white/60 px-3.5 py-1.5 text-xs font-medium text-neutral-600 backdrop-blur-md dark:border-white/10 dark:bg-white/[0.05] dark:text-neutral-300">
207	          <Gift size={13} style={{ color: "var(--accent)" }} />
208	          Get {SIGNUP_GRANT} free credits — enough for a real site and a few edits
209	        </span>
210	      </div>
211	
212	      {/* This inner wrapper is sized to exactly the composer box — the glow
213	          layers below position with -inset-N relative to IT specifically,
214	          not the outer component (which also holds the badge and suggestion
215	          chips), so the glow hugs just the box, never the whole component. */}
216	      <div className="relative">
217	      {/* The glow — a Gemini-style "chasing light" ring, rebuilt with only
218	          plain `transform: rotate()` + `overflow: hidden` clipping — no
219	          @property, no CSS masking (dropped after those didn't visibly
220	          work even in a fresh, verified non-cached browser). Two layers:
221	          a thin bright one (-inset-[7px]) and a soft blurred halo
222	          (-inset-[22px]). Deliberately NOT the page's big ambient .aura
223	          blobs (Aura.tsx), a separate, much larger, static effect.
224	
225	          The blur lives on the CLIP element, not on the rotating child.
226	          That ordering matters: filters apply AFTER the element (and its
227	          overflow:hidden clipping) is rendered, so the blur softens the
228	          clip's hard outer cutoff and lets the light bleed beyond the
229	          clip's bounds — a real falloff. With the blur on the child
230	          instead, the clip's crisp edge survives and the result reads as
231	          a chunky solid border rather than a glow.
232	
233	          Each layer's blur radius therefore wants to be comparable to or
234	          larger than its own inset, so the band never looks like a hard
235	          stripe. Opacities are deliberately well under 1 (see
236	          glow-fade-in-a/-b) — at full strength the brand colors read as a
237	          saturated ring instead of ambient light.
238	
239	          Each layer is a STATIC outer clipper (glow-clip-*, overflow:
240	          hidden, never transforms) containing one OVERSIZED inner
241	          rotator (glow-spin-*, ~2x the clipper's size via inset:-50%,
242	          centered). Only the inner rotator spins — being oversized, its
243	          corners sweeping outside a same-sized box (the original "wide
244	          rectangle rotated as a rigid body swings outside its footprint"
245	          bug) never matters, since the static outer box clips them away
246	          at every angle. The opaque composer sitting on top (z-10) covers
247	          the rotator's entire interior on its own, leaving only the outer
248	          few px visible as a ring — no masking needed for that either.
249	
250	          Opacity is fixed, not keyed off `focused` — an earlier version
251	          dimmed on blur, which read as "disappearing." The composer's own
252	          border/shadow below is the right place for a focus affordance;
253	          this ambient ring stays constant.
254	
255	          Entrance: fade+scale in once via the glow-fade-in-a/-b keyframes
256	          on the outer clipper (globals.css) — plain CSS, not a
257	          framer-motion `whileInView`.
258	
259	          NO NEGATIVE Z-INDEX HERE — this was the "it appears for a moment
260	          on load, then is gone for good" bug. PromptHero is wrapped in
261	          <Reveal>, which animates opacity 0 -> 1. An element with opacity
262	          BETWEEN 0 and 1 establishes a stacking context, which kept these
263	          layers painting above the page background while the reveal ran.
264	          The moment opacity reached exactly 1 that stacking context was
265	          destroyed, and `-z-10` dropped the layers behind the root page
266	          div's opaque bg-white / dark:bg-neutral-950 — invisible, forever.
267	          Instead the layers now sit at the default level (painting above
268	          the page background) and the composer is lifted above THEM with
269	          z-10, which needs no stacking-context trickery to hold. */}
270	      <div aria-hidden className="glow-clip-a pointer-events-none absolute -inset-[3px] overflow-hidden rounded-[1.9rem] blur-[5px]">
271	        <div
272	          className="glow-spin-a"
273	          style={{
274	            ...SPIN_SQUARE,
275	            // Stops are pushed into distinct quadrants (rather than the
276	            // near-adjacent pink/coral/orange run they used to be) so the
277	            // colour visibly travels around the box as this rotates —
278	            // closely-spaced hues just blur into one flat pink.
279	            background:
280	              "conic-gradient(#f72570 0deg, #a33dff 90deg, #ff9868 180deg, #ff6b67 270deg, #f72570 360deg)",
281	          }}
282	        />
283	      </div>
284	      <div aria-hidden className="glow-clip-b pointer-events-none absolute -inset-[14px] overflow-hidden rounded-[2.4rem] blur-[22px]">
285	        <div
286	          className="glow-spin-b"
287	          style={{
288	            ...SPIN_SQUARE,
289	            background:
290	              "conic-gradient(from 180deg, #a33dff 0deg, #f72570 90deg, #ff9868 180deg, #ff6b67 270deg, #a33dff 360deg)",
291	          }}
292	        />
293	      </div>
294	
295	      {/* The glass composer. Opaque enough that the animated ring behind it
296	          (see above) reads as a halo around the box, not a wash bleeding
297	          through onto the text — earlier versions were translucent enough
298	          that the strong glow behind showed straight through onto the
299	          placeholder/input text. Still picks up a faint frosted quality from
300	          backdrop-blur, just not at the cost of legibility. */}
301	      <div
302	        className="relative z-10 overflow-hidden rounded-[1.75rem] bg-white/95 backdrop-blur-2xl backdrop-saturate-150 transition-colors duration-300 dark:bg-neutral-950/95"
303	        style={{
304	          // No focus-driven glow here — the animated ring behind the box is
305	          // the only glow, and a second one on focus fought with it. Focus
306	          // is still signalled (it must be, for keyboard users) but with a
307	          // quiet border shift instead.
308	          border: `1.5px solid ${
309	            focused
310	              ? "color-mix(in srgb, white 45%, var(--accent) 55%)"
311	              : "color-mix(in srgb, white 75%, var(--accent) 25%)"
312	          }`,
313	          boxShadow: "var(--sh-s), inset 0 1px 0 rgba(255,255,255,0.5)",
314	        }}
315	      >
316	        {image && (
317	          <div className="flex items-center gap-2 px-6 pt-4">
318	            <div className="relative h-12 w-12 overflow-hidden rounded-lg border border-black/10 dark:border-white/10">
319	              {/* eslint-disable-next-line @next/next/no-img-element */}
320	              <img src={image} alt="Attached reference" className="h-full w-full object-cover" />
321	              <button
322	                type="button"
323	                onClick={() => setImage(null)}
324	                aria-label="Remove attached image"
325	                className="absolute right-0.5 top-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-black/60 text-white"
326	              >
327	                <X size={10} strokeWidth={3} />
328	              </button>
329	            </div>
330	            <span className="text-xs text-neutral-500 dark:text-neutral-400">Reference image attached</span>
331	          </div>
332	        )}
333	
334	        {/* The spec is not a modal or a preview pane — it lands straight in the
335	            composer's own textarea, which is already editable and already the
336	            thing the send button reads. So "accept" is just pressing send,
337	            "edit" is typing, and "discard" is Revert. No new pattern, and no
338	            state where the user is stuck looking at something they can't
339	            change. */}
340	        {enhancedFrom !== null && (
341	          <div className="flex items-center justify-between gap-2 px-6 pt-4">
342	            <span className="inline-flex items-center gap-1.5 text-xs text-neutral-500 dark:text-neutral-400">
343	              <Sparkles size={13} style={{ color: "var(--accent)" }} />
344	              Expanded spec — edit anything before you build
345	            </span>
346	            <button
347	              type="button"
348	              onClick={revert}
349	              className="text-xs text-neutral-500 underline underline-offset-2 transition-colors hover:text-neutral-900 dark:text-neutral-400 dark:hover:text-white"
350	            >
351	              Revert
352	            </button>
353	          </div>
354	        )}
355	
356	        {enhanceError && (
357	          <p className="px-6 pt-4 text-xs text-neutral-500 dark:text-neutral-400">
358	            {enhanceError}
359	          </p>
360	        )}
361	
362	        <textarea
363	          value={value}
364	          onChange={(e) => setValue(e.target.value)}
365	          onFocus={() => setFocused(true)}
366	          onBlur={() => setFocused(false)}
367	          onKeyDown={(e) => {
368	            // Enter sends a one-liner, but while a spec is on screen this box
369	            // is a multi-line editor — there, Enter has to make a newline or
370	            // the first paragraph break the user types starts a build of a
371	            // half-edited spec. The send button still works either way.
372	            if (e.key === "Enter" && !e.shiftKey && enhancedFrom === null) {
373	              e.preventDefault();
374	              submit();
375	            }
376	          }}
377	          // A ~200-word spec in a two-row box is unreviewable, and an
378	          // unreviewed spec defeats the whole feature — grow to fit it.
379	          rows={enhancedFrom !== null ? 12 : 2}
380	          placeholder={listening ? "Listening…" : "Describe the site you want to build…"}
381	          className="w-full resize-none bg-transparent px-6 pb-14 pt-5 text-[15px] leading-relaxed text-neutral-900 outline-none placeholder:text-neutral-500 dark:text-white dark:placeholder:text-neutral-400"
382	        />
383	
384	        <div className="absolute bottom-3 left-3 flex items-center gap-1">
385	          <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={onPickImage} />
386	          <button
387	            type="button"
388	            onClick={() => fileInputRef.current?.click()}
389	            aria-label="Attach an image"
390	            className="flex h-9 w-9 items-center justify-center rounded-full text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
391	          >
392	            <Paperclip size={16} strokeWidth={2} />
393	          </button>
394	          {speechSupported && (
395	            <button
396	              type="button"
397	              onClick={toggleListening}
398	              aria-label={listening ? "Stop voice input" : "Start voice input"}
399	              className={`relative flex h-9 w-9 items-center justify-center rounded-full transition-colors ${
400	                listening
401	                  ? "text-white"
402	                  : "text-neutral-500 hover:bg-black/5 hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
403	              }`}
404	              style={listening ? { background: "var(--brand-gradient)" } : undefined}
405	            >
406	              {listening && (
407	                <motion.span
408	                  className="absolute inset-0 rounded-full"
409	                  style={{ background: "var(--brand-gradient)" }}
410	                  animate={{ opacity: [0.5, 0, 0.5], scale: [1, 1.6, 1] }}
411	                  transition={{ duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
412	                />
413	              )}
414	              <Mic size={16} strokeWidth={2} className="relative" />
415	            </button>
416	          )}
417	          {enhanceSupported && (
418	            <button
419	              type="button"
420	              onClick={enhance}
421	              disabled={enhancing || !value.trim()}
422	              aria-label="Expand this into a fuller spec you can edit"
423	              className="flex h-9 items-center gap-1.5 rounded-full px-3 text-xs font-medium text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-900 disabled:pointer-events-none disabled:opacity-40 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
424	            >
425	              <Sparkles size={14} strokeWidth={2} />
426	              {enhancing ? "Enhancing…" : "Enhance"}
427	            </button>
428	          )}
429	        </div>
430	
431	        <motion.button
432	          type="button"
433	          onClick={submit}
434	          disabled={!value.trim()}
435	          aria-label="Start building"
436	          whileHover={value.trim() ? { scale: 1.06 } : undefined}
437	          whileTap={value.trim() ? { scale: 0.94 } : undefined}
438	          className="absolute bottom-3 right-3 flex h-9 w-9 items-center justify-center rounded-full text-white shadow-[0_6px_18px_-4px_var(--glow)] transition-opacity disabled:opacity-30"
439	          style={{ background: "var(--brand-gradient)" }}
440	        >
441	          <ArrowUp size={16} strokeWidth={2.5} />
442	        </motion.button>
443	      </div>
444	
445	      </div>
446	
447	      <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
448	        {SUGGESTIONS.map((s) => (
449	          <button
450	            key={s}
451	            type="button"
452	            onClick={() => setValue(s)}
453	            className="rounded-full border border-neutral-200/70 bg-white/50 px-3.5 py-1.5 text-xs text-neutral-600 backdrop-blur-md transition-colors hover:border-neutral-300 hover:text-neutral-900 dark:border-white/10 dark:bg-white/[0.04] dark:text-neutral-400 dark:hover:text-white"
454	          >
455	            {s}
456	          </button>
457	        ))}
458	      </div>
459	    </div>
460	  );
461	}
