1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { motion, AnimatePresence, useReducedMotion, type Variants } from "framer-motion";
5	import { Check } from "lucide-react";
6	import { Mark } from "./Logo";
7	
8	const PROMPT_TEXT = "A boutique pilates studio with online class booking";
9	
10	const PHASE_DURATIONS = { typing: 2600, building: 2400, live: 5400 } as const;
11	type Phase = "typing" | "building" | "live";
12	const NEXT_PHASE: Record<Phase, Phase> = { typing: "building", building: "live", live: "typing" };
13	
14	// A real booking flow plays out during the "live" phase, not just a static
15	// page — the demo is meant to look like a working app, not a brochure.
16	type BookingStep = "browse" | "clicking" | "confirmed";
17	const BOOKING_DURATIONS: Record<BookingStep, number> = { browse: 1700, clicking: 600, confirmed: 2800 };
18	const NEXT_BOOKING: Record<BookingStep, BookingStep> = { browse: "clicking", clicking: "confirmed", confirmed: "browse" };
19	const BOOKING_TARGET_INDEX = 0;
20	
21	// One fixed frame height, used for every phase — previously the frame
22	// animated its own height per phase, which shifted every section below it
23	// on the page (a visible jitter). Shorter phases just center within the
24	// same fixed space now, so the page around it never moves. Sized to the
25	// live phase's actual content (measured ~363px) plus a little breathing
26	// room — the old 620px value was sized for the earlier Studio Nine demo's
27	// taller content and left a large dead-space gap under this one.
28	const FRAME_HEIGHT = 410;
29	
30	const container: Variants = {
31	  hidden: {},
32	  shown: { transition: { staggerChildren: 0.11, delayChildren: 0.1 } },
33	};
34	const item: Variants = {
35	  hidden: { opacity: 0, y: 12 },
36	  shown: { opacity: 1, y: 0, transition: { duration: 0.5, ease: [0.2, 0.9, 0.2, 1] } },
37	};
38	const blockVariants: Variants = {
39	  hidden: { opacity: 0, scale: 0.85 },
40	  shown: { opacity: 1, scale: 1, transition: { duration: 0.4, ease: [0.2, 0.9, 0.2, 1] } },
41	};
42	
43	function useTypewriter(text: string, active: boolean, msPerChar: number) {
44	  const [count, setCount] = useState(0);
45	  useEffect(() => {
46	    if (!active) {
47	      setCount(0);
48	      return;
49	    }
50	    const id = setInterval(() => {
51	      setCount((c) => (c >= text.length ? c : c + 1));
52	    }, msPerChar);
