13	  function toggle() {
14	    const next = !document.documentElement.classList.contains("dark");
15	    document.documentElement.classList.toggle("dark", next);
16	    document.documentElement.classList.toggle("light", !next);
17	    try {
18	      localStorage.setItem("kodely-theme", next ? "dark" : "light");
19	    } catch {}
20	    setDark(next);
21	  }
22	
23	  return (
24	    <button
25	      type="button"
26	      onClick={toggle}
27	      aria-label="Toggle theme"
28	      className="grid h-9 w-9 place-items-center rounded-lg border border-neutral-200 text-neutral-600 transition-colors hover:border-neutral-400 hover:text-neutral-900 dark:border-neutral-800 dark:text-neutral-400 dark:hover:border-neutral-600 dark:hover:text-white"
29	    >
30	      {dark === null ? null : dark ? <Sun size={15} /> : <Moon size={15} />}
31	    </button>
32	  );
33	}
