147	/* Entrance fade-in — plain CSS on the static outer clipper, not a
148	   framer-motion `whileInView` (depends on IntersectionObserver + React
149	   state + framer's scheduling — more moving parts than necessary here).
150	   `forwards` is load-bearing: without it, the element snaps back to its
151	   non-animated base style the instant the single iteration ends. */
152	@keyframes glow-fade-in-a {
153	  from {
154	    opacity: 0;
155	    transform: scale(0.94);
156	  }
157	  to {
158	    opacity: 0.35;
159	    transform: scale(1);
160	  }
161	}
162	@keyframes glow-fade-in-b {
163	  from {
164	    opacity: 0;
165	    transform: scale(0.94);
166	  }
167	  to {
168	    opacity: 0.2;
169	    transform: scale(1);
170	  }
171	}
