173	/* Ambient pulse — a slow breathe, kept subtle so it reads as the glow
174	   "living" rather than blinking. Runs as a THIRD animation chained after
175	   the entrance: the fade-in owns opacity for its first 0.8s, then this
176	   takes over from the same value it settled on (0.35 / 0.2), so there is
177	   no jump at the handoff — keep the two in sync when retuning intensity.
178	   Its delay must match the fade-in's duration.
179	   The floor never approaches 0 — the glow dims and brightens, it never
180	   disappears. */
181	@keyframes glow-pulse-a {
182	  0%,
183	  100% {
184	    opacity: 0.35;
185	  }
186	  50% {
187	    opacity: 0.5;
188	  }
189	}
190	@keyframes glow-pulse-b {
191	  0%,
192	  100% {
193	    opacity: 0.2;
194	  }
195	  50% {
196	    opacity: 0.33;
197	  }
198	}
