210	/* Scroll entrance for the hero mock (HeroMock.tsx). A CSS transition
211	   toggled by an `is-entered` class from an IntersectionObserver — no
212	   dependence on framer-motion's in-view scheduling, which applied its
213	   initial styles here but never actually triggered. */
214	@keyframes hero-mock-in {
215	  from {
216	    opacity: 0;
217	    transform: translateY(56px) scale(0.94);
218	  }
219	  to {
220	    opacity: 1;
221	    transform: translateY(0) scale(1);
