232	/* The real thing: a native scroll-driven animation, progressed by the
233	   element's own position in the viewport. No IntersectionObserver, no
234	   scroll listener, no React state — every JS-based trigger tried here
235	   (framer's whileInView, a raw IntersectionObserver, a scroll listener)
236	   failed to fire in practice, and this removes that entire class of
237	   failure. `view()` ties progress to the element crossing the viewport;
238	   the range runs from just after it appears to a third of the way up, so
239	   it finishes as you arrive at it rather than while it's still an
240	   off-screen sliver. */
241	@supports (animation-timeline: view()) {
242	  .hero-mock-enter {
243	    /* Longhands, not the `animation` shorthand: the shorthand defaults
244	       animation-duration to 0s when it's omitted, which — combined with
245	       fill:both — snapped straight to the end state at every scroll
246	       position (i.e. no visible animation at all). Scroll-driven
247	       animations need `auto`, which maps progress onto animation-range.
248	       The shorthand also resets animation-timeline, so setting these
249	       individually keeps the two declarations from fighting. */
250	    animation-name: hero-mock-in;
251	    animation-duration: auto;
252	    animation-timing-function: linear;
253	    animation-fill-mode: both;
254	    animation-timeline: view();
255	    /* Spans the element's whole entry into the viewport: starts just after
256	       its top edge appears and finishes exactly when it's fully on screen.
257	       Both endpoints in the same phase keeps it predictable (an earlier
258	       `entry 15% cover 38%` mixed phases, which is legal but harder to
259	       reason about and compressed the motion into a shorter scroll). */
260	    animation-range: entry 10% entry 100%;
261	  }
262	}
