269	/** The one real hero object — a miniature browser frame that plays out the
270	 * actual product loop (type a prompt → watch it build → it's live at a real
271	 * URL) instead of showing a single static screenshot. Loops continuously;
272	 * respects prefers-reduced-motion by settling on the finished "live" frame. */
273	export function HeroMock() {
274	  const reduced = useReducedMotion();
275	  const [phase, setPhase] = useState<Phase>(reduced ? "live" : "typing");
276	  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
277	
278	  useEffect(() => {
279	    if (reduced) return;
280	    timeoutRef.current = setTimeout(() => {
281	      setPhase((p) => NEXT_PHASE[p]);
282	    }, PHASE_DURATIONS[phase]);
283	    return () => {
284	      if (timeoutRef.current) clearTimeout(timeoutRef.current);
285	    };
286	  }, [phase, reduced]);
287	
288	  return (
289	    // The scroll entrance is entirely CSS — see .hero-mock-enter in
290	    // globals.css, which uses a native scroll-driven animation
291	    // (animation-timeline: view()). There is deliberately no JS trigger
292	    // here: framer's whileInView, a raw IntersectionObserver and a scroll
293	    // listener were each tried and none fired reliably in practice.
294	    <div className="mx-auto w-full max-w-2xl hero-mock-enter" style={{ perspective: "1800px" }}>
295	      <div className="group overflow-hidden rounded-2xl border border-black/10 bg-white shadow-[0_40px_80px_-32px_rgba(0,0,0,0.25)] transition-transform duration-500 [transform:rotateX(4deg)] hover:[transform:rotateX(0deg)] dark:border-white/10 dark:bg-neutral-900">
296	        <div className="flex items-center gap-2 border-b border-black/10 bg-black/[0.03] px-4 py-2.5 dark:border-white/10 dark:bg-white/[0.03]">
297	          <span className="h-2.5 w-2.5 rounded-full bg-black/15 dark:bg-white/15" />
298	          <span className="h-2.5 w-2.5 rounded-full bg-black/15 dark:bg-white/15" />
299	          <span className="h-2.5 w-2.5 rounded-full bg-black/15 dark:bg-white/15" />
300	          <div className="ml-3 flex-1 overflow-hidden rounded-md bg-black/[0.04] px-3 py-1 text-center font-mono text-[11px] text-black/55 dark:bg-white/[0.06] dark:text-white/55">
301	            <AnimatePresence mode="wait">
302	              {phase === "live" ? (
303	                <motion.span key="url" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
304	                  bloom-pilates.kodely.site
305	                </motion.span>
306	              ) : (
307	                <motion.span key="new" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
308	                  new-project.kodely.site
309	                </motion.span>
310	              )}
311	            </AnimatePresence>
312	          </div>
313	          <div className="hidden items-center gap-1.5 font-mono text-[10px] text-black/55 sm:flex dark:text-white/55">
314	            {phase === "live" ? (
315	              <>
316	                <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]" />
317	                Generated by Kodely
318	              </>
319	            ) : (
320	              <>
321	                <span className="h-1.5 w-1.5 rounded-full bg-neutral-300 dark:bg-neutral-700" />
